/* @layer shared-asset-extraction @kind logic */
import { romRegion } from '../rom/hirom';
import { hexRows } from './c-text';

/** The flat file offset of $C3:E000, and the 8 KB to $C3:FFFF. */
const BASE = 0x03e000;
const SIZE = 0x2000;

/** tools/gen/ow_anim.py: the overworld anim sub-VM bytecode (ROM bank $C3) as src/data/ow_anim.h. */
const genOwAnim = (rom: Uint8Array): string => {
  const blob = romRegion(rom, BASE, BASE + SIZE);
  const lines = [
    '// ow_anim.h - the overworld ANIM SUB-VM bytecode, verbatim from ROM $C3:E000..FFFF.',
    '// Generated by tools/gen/ow_anim.py -- DO NOT EDIT BY HAND.',
    "// Consumed by world.c's port of the interpreter C2/0E1D: the object's +0B/+0C pointer",
    '// (stamped from the table at $C3:E000 by object-VM op 0x30) indexes this blob, and the',
    '// handlers at C2/0E4A..0F34 read their operands from it.',
    '#ifndef CT_OW_ANIM_H',
    '#define CT_OW_ANIM_H',
    '#include <stdint.h>',
    '#define CT_OWANIM_BASE 0xE000u   /* the $C3 address the blob starts at */',
    `#define CT_OWANIM_SIZE 0x${SIZE.toString(16).toUpperCase()}u`,
    'static const uint8_t ctOwAnimC3[CT_OWANIM_SIZE] = {',
    ...hexRows(blob),
    '};',
    '#endif',
  ];
  return `${lines.join('\n')}\n`;
};

export { genOwAnim };
